function drawActorSprite(im,x,y,w,h,pose){
 ctx.save();ctx.translate(x+w/2,y+h);ctx.rotate(pose.idle?.lean||0);ctx.scale(w/im.width,h/im.height);ctx.translate(-im.width/2,-im.height);
 const blink=()=>{if(!pose.blink)return;ctx.fillStyle='#e6e6e6';for(const ex of [9,14])ctx.fillRect(ex,12,1,3);ctx.fillStyle='#5b4050';for(const ex of [9,14])ctx.fillRect(ex-.4,14,1.8,.65)};
 if(!pose.idle||['unwell','sway'].includes(pose.idle.name)){ctx.drawImage(im,0,0);blink()}
 else{
  const raisedArms=pose.idle.name==='stretch'&&pose.frame===7&&pose.idle.armRaise>.001;
  ctx.save();ctx.beginPath();ctx.rect(0,17,24,15);if(raisedArms){ctx.rect(5,20,3,5);ctx.rect(16,20,3,5)}ctx.clip('evenodd');ctx.drawImage(im,0,0);ctx.restore();
  if(raisedArms)for(const [sx,pivot,sign]of [[5,7,1],[16,17,-1]]){ctx.save();ctx.translate(pivot,20);ctx.rotate(sign*pose.idle.armRaise);ctx.drawImage(im,sx,20,3,5,sx-pivot,0,3,5);ctx.restore()}
  ctx.save();ctx.translate(12,17);ctx.rotate(pose.idle.headTilt);ctx.translate(-12,-17);ctx.drawImage(im,0,0,24,17,0,0,24,17);blink();ctx.restore();
 }
 ctx.restore();
}
