 const pose=ActorMotion.pose(body,mikuSpeaking?time+dialogue.clock:time,allowIdle),im=name==='haku'?textures.haku:name==='teto_2'?ActorSpriteArt.clean(textures[`${name}_${pose.frame}`]):textures[`${name}_${pose.frame}`];
