// Rotating octahedron: real changing facets, not a flat image squashed left and right.
function crystalGeometry(t){const angle=t*1.1,ring=[];for(let i=0;i<4;i++){const a=angle+i*Math.PI/2;ring.push({x:Math.cos(a)*14,y:Math.sin(a)*3.5,z:Math.sin(a)*14})}const top={x:0,y:-29,z:0},bottom={x:0,y:29,z:0},faces=[];for(let i=0;i<4;i++){const a=ring[i],b=ring[(i+1)%4];faces.push({points:[top,a,b],depth:(a.z+b.z)/3,lower:false,index:i});faces.push({points:[bottom,b,a],depth:(a.z+b.z)/3,lower:true,index:i})}return faces.sort((a,b)=>a.depth-b.depth)}
function drawCrystal(cx=1161,baseY=343){const fade=MikuRupture.opacity('decor');if(fade<=0)return;const cy=baseY+Math.sin(time*1.9)*3;ctx.save();ctx.globalAlpha*=fade;ctx.shadowColor='#9fffff';ctx.shadowBlur=14;for(const f of crystalGeometry(time)){const light=Math.max(0,Math.min(1,(f.depth+10)/20)),v=Math.round(72+light*22-(f.lower?9:0));ctx.fillStyle=`hsl(177 88% ${v}%)`;ctx.strokeStyle='#d6ffff';ctx.lineWidth=1.5;ctx.beginPath();f.points.forEach((p,i)=>{const x=cx+p.x,y=cy+p.y;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();ctx.fill();ctx.stroke()}ctx.shadowBlur=0;for(let i=0;i<4;i++){const a=time*.65+i*Math.PI/2,x=cx+Math.cos(a)*39,y=cy+Math.sin(a)*22,alpha=.3+.6*(.5+.5*Math.sin(time*2+i*1.7));ctx.globalAlpha=alpha*fade;ctx.fillStyle='#e7ffff';ctx.fillRect(Math.round(x)-1,Math.round(y)-4,2,8);ctx.fillRect(Math.round(x)-4,Math.round(y)-1,8,2)}ctx.restore()}

