function markIntroSeen(){if(MikuHearts.released){Object.assign(miku,HeartRoadData.crossroads.mikuRest,{moving:false});trail=[{x:teto.x,y:teto.y}];}introSeen=true;try{localStorage.setItem('smile-intro-seen-v1','1')}catch{}}
function beginEntrance(replayDialogue=false){townPassage.active=false;townPassage.cooldown=0;W.setZone('outdoor');locationId='meadow';transition.active=false;camera.snap(0);intro.active=true;intro.elapsed=0;intro.replayDialogue=replayDialogue;paused=false;teto.x=766;teto.y=1125;teto.dir=0;teto.walk=0;miku.x=766;miku.y=1210;miku.dir=0;miku.walk=0;trail=[{x:miku.x,y:miku.y},{x:teto.x,y:teto.y}];keys.clear();destination=[];resetActorIdle();document.querySelector('#world-inventory').disabled=true;}
function updateEntrance(dt){time+=dt;intro.elapsed+=dt;const oldT={x:teto.x,y:teto.y},oldM={x:miku.x,y:miku.y},u=Math.max(0,Math.min(1,(intro.elapsed-.15)/2.4)),v=Math.max(0,Math.min(1,(intro.elapsed-.45)/2.75)),side=Math.max(0,Math.min(1,(v-.65)/.35));teto.x=766;teto.y=1125-315*u;miku.x=766+57*side*side*(3-2*side);miku.y=1210-355*v;ActorMotion.update(teto,oldT,dt);ActorMotion.update(miku,oldM,dt);if(intro.elapsed>=3.25){intro.active=false;teto.x=766;teto.y=810;teto.dir=1;teto.moving=false;miku.x=823;miku.y=855;miku.dir=3;miku.moving=false;trail=[{x:823,y:855},{x:795,y:833},{x:766,y:810}];document.querySelector('#world-inventory').disabled=false;if(!introSeen||intro.replayDialogue)DialogueUI.open(DialogueData.intro,{onDone:markIntroSeen});}}
function replayEntrance(){townPassage.active=false;NeruEncounter.cancel();MikuAftermath.cancel();MikuRupture.cancel();HeartGamesUI.cancel();HeartQuest.cancel();trialArrival=0;MikuHearts.cancel();DeathReturn.cancel();rearPassage.active=false;GumiEncounter.cancel();TentJourney.cancel();WorldOutcome.cancel(false);BattleUI.close();PauseUI.close(false);GuildBoardUI.close(false);if(DialogueUI.isOpen)DialogueUI.close(false);ChaptersUI.close(false);SaveUI.close();InventoryUI.close();ShopUI.close();if(helpOpen)closeHelp();beginEntrance(true);notify('Повтор вступления · тест',3);}
function beginTownPassage(to,kind='walk'){if(townPassage.active||townPassage.cooldown>0)return false;Object.assign(townPassage,{active:true,age:0,to,from:locationId,kind,changed:false});keys.clear();destination=[];resetActorIdle();document.querySelector('#world-inventory').disabled=true;return true;}
function updateTownPassage(dt){townPassage.age+=dt;if(!townPassage.changed&&townPassage.age>=.44){townPassage.changed=true;if(townPassage.to===HomeData.id)placeParty(HomeData.id,HomeData.spawn,HomeData.companion);else if(townPassage.to===TownData.id){if(townPassage.from===HomeData.id)placeParty(TownData.id,HomeData.outside.teto,HomeData.outside.miku);else placeParty(TownData.id,TownData.spawn,TownData.companion);}else placeParty('meadow',TownData.meadowArrival.teto,TownData.meadowArrival.miku);}if(townPassage.age>=1.0){townPassage.active=false;townPassage.cooldown=1.0;document.querySelector('#world-inventory').disabled=false;notify(locationName(locationId),3);SaveUI.saveNow(locationId===HomeData.id?'Дом Тето и Мику':locationId===TownData.id?'Город · прибытие':'Поляна · возвращение из города');}}
function drawTownPassage(g){if(!townPassage.active)return;const age=townPassage.age,a=age<.44?age/.44:1-(age-.44)/.56;g.save();g.fillStyle=townPassage.kind==='portal'?'rgba(13,58,65,'+Math.max(0,Math.min(1,a))+')':'rgba(3,16,17,'+Math.max(0,Math.min(1,a))+')';g.fillRect(0,0,1536,1024);if(townPassage.kind==='portal'){g.globalAlpha=Math.sin(Math.min(1,age)*Math.PI)*.6;g.fillStyle='#adffff';for(let i=0;i<30;i++){const f=(age*2+i*.137)%1;g.fillRect(768+Math.cos(i*2.4)*(260-200*f),512+Math.sin(i*2.4)*(190-150*f),4,4);}}g.restore();}
function interactHome(){keys.clear();destination=[];const near=HomeArt.nearby(teto);if(near?.type==='exit'){beginTownPassage(TownData.id,'home');return;}if(near?.type==='save'){SaveUI.open();return;}if(near?.item){DialogueUI.open({start:'home',nodes:{home:{speaker:'Тето',face:'happy',text:near.item.text,choices:[{label:'Продолжить осмотр.'}]}}});return;}if((!MikuHearts.released||HeartQuest.flags.mikuRecovered)&&ActorMotion.facesTarget(teto,miku))DialogueUI.open({start:'home',nodes:{home:{speaker:'Мику',face:'happy',text:'Как хорошо снова быть дома. Давай немного побудем здесь вместе.',choices:[{label:'Мы дома.'}]}}});else notify('E — осмотреть вещи или поговорить с Мику. Выход — внизу комнаты Тето.',3);}
function interactTown(){const near=TownArt.nearby(teto);keys.clear();destination=[];if(near?.type==='home'){beginTownPassage(HomeData.id,'home');return;}if(near?.type==='resident'){DialogueUI.open(TownPeople.dialogue(near.target));return;}if(near?.type==='vendor'){ShopUI.open(null,{vendor:'Хару'});return;}if(near?.type==='portal'){if(travelLocked()){notify(HeartQuestModel.travelMessage,3);return;}DialogueUI.open({start:'portal',nodes:{portal:{speaker:'Тето',face:'neutral',text:'Кристаллы откликаются. Этот портал ведёт обратно на Тихую поляну.',choices:[{label:'Перенестись на поляну.',townDestination:'meadow'},{label:'Остаться в городе.'}]}}},{onDone(result){if(result.completed&&result.choice?.townDestination==='meadow')beginTownPassage('meadow','portal');}});return;}if(near?.type==='guild'){GuildBoardUI.open();return;}if((!MikuHearts.released||HeartQuest.flags.mikuRecovered)&&ActorMotion.facesTarget(teto,miku))DialogueUI.open(DialogueData.miku);else if(Math.hypot(teto.x-miku.x,teto.y-miku.y)<115)notify('Повернись к Мику, чтобы поговорить.',2.5);else notify('E — осмотреть лавку, портал, доску гильдии или войти домой.',3);}
function beginRearPassage(to){if(rearPassage.active||!GumiEncounter.defeated)return;Object.assign(rearPassage,{active:true,age:0,to,changed:false});keys.clear();destination=[];teto.moving=miku.moving=false;document.querySelector('#world-inventory').disabled=true;}
function updateRearPassage(dt){rearPassage.age+=dt;if(!rearPassage.changed&&rearPassage.age>=.5){rearPassage.changed=true;const d=rearPassage.to==='circus'?CircusData.tent.rearDoor.arrival:InteriorData.arena.rearExit.arrival;placeParty(rearPassage.to,d.teto,d.miku);}if(rearPassage.age>=1.15){rearPassage.active=false;rearPassage.cooldown=1.5;document.querySelector('#world-inventory').disabled=false;notify(rearPassage.to==='circus'?'Обратная сторона шатра':'За занавесом',3);}}
