function developerWarp(slot){const snapshot=DeveloperPresets.prepare(captureSnapshot(),slot);snapshot.gameVersion=LevelData.version;if(!SaveModel.valid(snapshot))throw Error('Эта точка пока недоступна.');SaveUI.close();if(helpOpen)closeHelp();restoreSnapshot(snapshot);const name=DeveloperPresets.find(slot).title,result=SaveUI.saveNow('Тест · '+name);notify(result.ok?'Воспоминание открыто. Создана отдельная копия.':'Переход выполнен, но копию сохранить не удалось.',4);return true;}
function placeParty(location,t,m){PartyFollower.reset();locationId=location;W.setZone(collisionZone(location));transition.active=false;camera.snap(locationCamera(location));Object.assign(teto,t,{moving:false,walk:0});Object.assign(miku,MikuHearts.companion(location,m),{moving:false,walk:0});trail=MikuHearts.released&&!HeartQuest.flags.mikuRecovered?[{x:teto.x,y:teto.y}]:[{x:miku.x,y:miku.y},{x:teto.x,y:teto.y}];keys.clear();destination=[];resetActorIdle();if(locationId===TownData.id||locationId===HomeData.id){W.recover(teto);if(!MikuHearts.released||HeartQuest.flags.mikuRecovered)W.recover(miku);trail=MikuHearts.released&&!HeartQuest.flags.mikuRecovered?[{x:teto.x,y:teto.y}]:[{x:miku.x,y:miku.y},{x:teto.x,y:teto.y}];if(locationId===TownData.id)camera.follow(teto,TownData,0,true);}}
